package com.smarthospital.controller;
import com.smarthospital.model.User;import com.smarthospital.util.*;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import java.io.*;import java.nio.file.*;import java.sql.*;import java.util.*;
@WebServlet("/documents") @MultipartConfig(maxFileSize=5242880,maxRequestSize=10485760)
public class DocumentServlet extends HttpServlet{
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");try(Connection c=DB.getConnection()){req.setAttribute("docs",docs(c,u));if(Access.isStaff(u))req.setAttribute("assignments",myAssignments(c,u));req.getRequestDispatcher("/documents.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException,ServletException{User u=(User)req.getSession().getAttribute("user");String action=req.getParameter("action");try{if(Access.isStaff(u)&&"upload".equals(action))upload(req,u);else if(!Access.isStaff(u)&&"review".equals(action))review(req,u);else throw new SecurityException("This action is not allowed for your role.");resp.sendRedirect(req.getContextPath()+"/documents");}catch(Exception e){resp.sendError(400,e.getMessage());}}
 private void upload(HttpServletRequest req,User u)throws Exception{Part part=req.getPart("file");if(part==null||part.getSize()==0)throw new IllegalArgumentException("Select a work-proof file.");String original=Path.of(part.getSubmittedFileName()).getFileName().toString();String lower=original.toLowerCase(Locale.ROOT);if(!(lower.endsWith(".jpg")||lower.endsWith(".jpeg")||lower.endsWith(".png")||lower.endsWith(".pdf")))throw new IllegalArgumentException("Only JPG, JPEG, PNG and PDF are allowed.");int dutyId=Integer.parseInt(req.getParameter("duty_id"));try(Connection c=DB.getConnection()){int sid=Access.ownStaffId(c,u.id());if(!assignedToDuty(c,sid,dutyId))throw new SecurityException("You can upload proof only for a duty assigned to you.");String root=getServletContext().getRealPath("/uploads");if(root==null)throw new IllegalStateException("Upload directory is unavailable.");Path dir=Path.of(root);Files.createDirectories(dir);String safe=System.currentTimeMillis()+"_"+original.replaceAll("[^a-zA-Z0-9._-]","_");part.write(dir.resolve(safe).toString());try(PreparedStatement p=c.prepareStatement("INSERT INTO documents(staff_id,duty_id,file_name,file_path,file_type) VALUES(?,?,?,?,?)")){p.setInt(1,sid);p.setInt(2,dutyId);p.setString(3,original);p.setString(4,"uploads/"+safe);p.setString(5,part.getContentType());p.executeUpdate();}try(PreparedStatement n=c.prepareStatement("INSERT INTO notifications(user_id,message,type) SELECT u.user_id,?,'WORK_PROOF_SUBMITTED' FROM users u JOIN supervisor_departments sd ON u.user_id=sd.supervisor_user_id WHERE u.role='SUPERVISOR' AND u.status='ACTIVE' AND sd.active=1 AND sd.department_id=(SELECT department_id FROM duties WHERE duty_id=?) UNION ALL SELECT u.user_id,?,'WORK_PROOF_SUBMITTED' FROM users u WHERE u.role='ADMIN' AND u.status='ACTIVE'")){n.setString(1,"Staff submitted work proof for duty #"+dutyId+". Please review it.");n.setInt(2,dutyId);n.setString(3,"Staff submitted work proof for duty #"+dutyId+". Please review it.");n.executeUpdate();}Audit.log(u.id(),"WORK_PROOF_UPLOADED",original);}}
 private void review(HttpServletRequest req,User u)throws Exception{int docId=Integer.parseInt(req.getParameter("document_id"));String status=req.getParameter("status");if(!"VERIFIED".equals(status)&&!"REJECTED".equals(status))throw new IllegalArgumentException("Invalid review status.");try(Connection c=DB.getConnection()){c.setAutoCommit(false);int dutyId=0,staffId=0;String staffName=null;try(PreparedStatement p=c.prepareStatement("SELECT doc.duty_id,doc.staff_id,s.name,s.department_id FROM documents doc JOIN staff s ON doc.staff_id=s.staff_id WHERE doc.document_id=?")){p.setInt(1,docId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Proof not found.");dutyId=r.getInt(1);staffId=r.getInt(2);staffName=r.getString(3);int dept=r.getInt(4);if(Access.isSupervisor(u)&&!Access.supervisorHasDepartment(c,u.id(),dept))throw new SecurityException("You can review only proof from your assigned department.");}}
 String note=req.getParameter("review_note");try(PreparedStatement p=c.prepareStatement("UPDATE documents SET verification_status=?,reviewed_by=?,reviewed_at=NOW(),review_note=? WHERE document_id=?")){p.setString(1,status);p.setInt(2,u.id());p.setString(3,note==null?"":note.trim());p.setInt(4,docId);p.executeUpdate();}
 if("VERIFIED".equals(status)&&dutyId>0){try(PreparedStatement p=c.prepareStatement("UPDATE duty_assignments SET status='COMPLETED' WHERE duty_id=? AND staff_id=? AND status<>'CANCELLED'")){p.setInt(1,dutyId);p.setInt(2,staffId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE duties SET status='COMPLETED' WHERE duty_id=? AND NOT EXISTS(SELECT 1 FROM duty_assignments WHERE duty_id=? AND status NOT IN ('COMPLETED','CANCELLED'))")){p.setInt(1,dutyId);p.setInt(2,dutyId);p.executeUpdate();}}
 try(PreparedStatement p=c.prepareStatement("SELECT user_id FROM staff WHERE staff_id=?")){p.setInt(1,staffId);try(ResultSet r=p.executeQuery()){if(r.next()&&r.getObject(1)!=null)try(PreparedStatement n=c.prepareStatement("INSERT INTO notifications(user_id,message,type) VALUES(?,?,?)")){n.setInt(1,r.getInt(1));n.setString(2,"Your work proof for "+(dutyId>0?"duty #"+dutyId:staffName)+" was "+status.toLowerCase()+".");n.setString(3,"WORK_PROOF_REVIEW");n.executeUpdate();}}}
 Audit.log(u.id(),"WORK_PROOF_REVIEW",docId+" -> "+status);c.commit();}}
 private boolean assignedToDuty(Connection c,int sid,int dutyId)throws Exception{try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM duty_assignments da JOIN duties d ON da.duty_id=d.duty_id WHERE da.duty_id=? AND da.staff_id=? AND da.status='IN_PROGRESS' AND d.status<>'CANCELLED'")){p.setInt(1,dutyId);p.setInt(2,sid);try(ResultSet r=p.executeQuery()){return r.next();}}}
 private List<Map<String,Object>> myAssignments(Connection c,User u)throws Exception{List<Map<String,Object>>l=new ArrayList<>();String q="SELECT da.assignment_id,d.duty_id,d.duty_name,d.duty_date,da.status FROM duty_assignments da JOIN duties d ON da.duty_id=d.duty_id JOIN staff s ON da.staff_id=s.staff_id WHERE s.user_id=? AND da.status IN ('ASSIGNED','ACKNOWLEDGED','IN_PROGRESS') ORDER BY d.duty_date DESC,d.start_time DESC";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,u.id());try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object>m=new HashMap<>();m.put("id",r.getInt(1));m.put("dutyId",r.getInt(2));m.put("name",r.getString(3));m.put("date",r.getDate(4));m.put("status",r.getString(5));l.add(m);}}}return l;}
 private List<Map<String,Object>> docs(Connection c,User u)throws Exception{List<Map<String,Object>>l=new ArrayList<>();String scope=Access.isStaff(u)?"s.user_id=?":Access.isAdmin(u)?"1=1":"s.department_id IN (SELECT department_id FROM supervisor_departments WHERE supervisor_user_id=? AND active=1)";String q="SELECT doc.document_id,s.staff_code,s.name,d.duty_name,doc.file_name,doc.file_type,doc.verification_status,doc.review_note,doc.uploaded_at FROM documents doc JOIN staff s ON doc.staff_id=s.staff_id LEFT JOIN duties d ON doc.duty_id=d.duty_id WHERE "+scope+" ORDER BY doc.uploaded_at DESC";try(PreparedStatement p=c.prepareStatement(q)){if(!Access.isAdmin(u))p.setInt(1,u.id());try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object>m=new HashMap<>();for(int i=1;i<=9;i++)m.put("c"+i,r.getObject(i));l.add(m);}}}return l;}
}
